### Computed Properties

```swift
struct Rectangle {
    var width: Double
    var height: Double

    // Computed property
    var area: Double {
        return width * height
    }

    // Get and set
    var perimeter: Double {
        get {
            return 2 * (width + height)
        }
        set {
            // newValue is automatic
            let side = newValue / 4
            width = side
            height = side
        }
    }

    // Read-only computed property
    var diagonal: Double {
        return (width * width + height * height).squareRoot()
    }
}

var rect = Rectangle(width: 10, height: 5)
print(rect.area)       // 50
print(rect.perimeter)  // 30
rect.perimeter = 40    // Sets width and height
print(rect.width)      // 10
```

