### Command Line Arguments

```swift
import Foundation

// Access command line arguments
let arguments = CommandLine.arguments

print("Program: \(arguments[0])")

if arguments.count > 1 {
    print("Arguments:")
    for (index, arg) in arguments.dropFirst().enumerated() {
        print("  \(index + 1): \(arg)")
    }
}

// Simple argument parser
struct Arguments {
    var name: String?
    var age: Int?
    var verbose: Bool = false

    init(args: [String]) {
        var i = 1
        while i < args.count {
            let arg = args[i]

            switch arg {
            case "-n", "--name":
                if i + 1 < args.count {
                    name = args[i + 1]
                    i += 1
                }
            case "-a", "--age":
                if i + 1 < args.count {
                    age = Int(args[i + 1])
                    i += 1
                }
            case "-v", "--verbose":
                verbose = true
            case "-h", "--help":
                printHelp()
                exit(0)
            default:
                print("Unknown argument: \(arg)")
            }

            i += 1
        }
    }

    func printHelp() {
        print("""
        Usage: program [options]

        Options:
          -n, --name NAME      Specify name
          -a, --age AGE        Specify age
          -v, --verbose        Enable verbose output
          -h, --help           Show this help
        """)
    }
}

let parsedArgs = Arguments(args: CommandLine.arguments)

if parsedArgs.verbose {
    print("Verbose mode enabled")
    print("Name: \(parsedArgs.name ?? "not provided")")
    print("Age: \(parsedArgs.age?.description ?? "not provided")")
}

// Usage: swift program.swift -n Alice -a 30 -v
```

