## Error Handling
Try-catch blocks and error handling
```swift
enum NetworkError: Error {
    case badURL
    case requestFailed
    case invalidResponse
    case decodingError
}

enum ValidationError: Error {
    case emptyString
    case tooShort
    case tooLong
}

// Function that throws
func validatePassword(_ password: String) throws -> Bool {
    if password.isEmpty {
        throw ValidationError.emptyString
    }
    if password.count < 6 {
        throw ValidationError.tooShort
    }
    if password.count > 20 {
        throw ValidationError.tooLong
    }
    return true
}

func fetchData(from url: String) throws -> String {
    if url.isEmpty {
        throw NetworkError.badURL
    }
    // Simulate network call
    return "Sample data"
}

// Using do-catch
do {
    try validatePassword("abc")
    print("Password is valid")
} catch ValidationError.emptyString {
    print("Password cannot be empty")
} catch ValidationError.tooShort {
    print("Password is too short")
} catch ValidationError.tooLong {
    print("Password is too long")
} catch {
    print("Unknown error: \(error)")
}

// Try? (converts to optional)
let data = try? fetchData(from: "https://example.com")
print("Data: \(data ?? "nil")")

// Try! (force try - crashes on error)
// let forcedData = try! fetchData(from: "")  // Crashes

// Defer statement
func processFile(filename: String) {
    print("Opening file")
    defer {
        print("Closing file")  // Executed when function exits
    }
    print("Processing file")
}

processFile(filename: "test.txt")
```

